// SPDX-License-Identifier: MIT
pragma solidity >=0.4.22 <0.9.0;

contract Elevate{

    uint public userCount=0;

    mapping(string => user) public usersList;

     struct user{
      string name;
      string email;
      string messgae;
  }

   // events

   event enquiryCreated(
      string name,
      string email,
      string messgae
    );

  function addEnquiry(string memory _name , string memory _email,string memory _messgae) public {

        userCount++;

        usersList[_name] = user(_name,_email,_messgae );

        emit enquiryCreated(_name,_email,_messgae);
    }

    //Address --> Contract -- deposit
    function deposit() external payable {
    }

    //Contract --> Address  -- withdrawal
    function withdraw(address payable _to, uint _amount) external {
        _to.transfer(_amount);
    }

    function getBalance() external view returns(uint) {
        return address(this).balance;
    }

    function getAddress() external view returns(address) {
        return address(this);
    }


}
